static uint32_t ticks;static uint32_t time_ms(void*unused){(void)unused;return ticks;}static bool uart_available(void*unused){(void)unused;return true;}static ls_result_t uart_send(void*unused,const uint8_t*bytes,size_t count){(void)unused;for(size_t i=0;i<count;i++)printf("%02x",bytes[i]);puts("");return LS_OK;}static size_t uart_mtu(void*unused){(void)unused;return LS_MAX_EVENT_SIZE;}int main(void){static uint8_t retained[18000];ls_memory_storage_t ram={retained,sizeof retained};ls_identity_t id={.project_id="demo",.device_id="host-01",.product="Latch demo",.firmware_version="0.1.0",.firmware_build_id="dev"};ls_config_t cfg={.identity=&id,.timestamp_ms=time_ms};ls_storage_backend_t storage={.name="noinit",.context=&ram,.capacity=sizeof retained,.read=ls_memory_storage_read,.write=ls_memory_storage_write,.erase=ls_memory_storage_erase};ls_transport_backend_t uart={.name="uart",.priority=10,.available=uart_available,.send=uart_send,.max_payload=uart_mtu};ls_init(&cfg);ls_storage_register(&storage);ls_transport_register(&uart);ls_boot();ls_breadcrumb("boot_complete");ticks=155;ls_metric_u32("battery_mv",3264);ls_capture_message("sensor timeout",LS_SEVERITY_ERROR);return ls_flush()!=LS_OK;}
